import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CZo9GF0W.js";const p=JSON.parse('{"title":"00 — Product Overview","description":"","frontmatter":{},"headers":[],"relativePath":"00-OVERVIEW.md","filePath":"00-OVERVIEW.md","lastUpdated":1789060268000}'),r={name:"00-OVERVIEW.md"};function s(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="_00-—-product-overview" tabindex="-1">00 — Product Overview <a class="header-anchor" href="#_00-—-product-overview" aria-label="Permalink to &quot;00 — Product Overview&quot;">​</a></h1><p><strong>Working name:</strong> Pitta (extension id <code>pitta-db</code>, publisher TBD) <strong>One line:</strong> A first-class PostgreSQL client inside VS Code — browse and edit visually, or write SQL — with a pluggable driver layer so other engines slot in later.</p><p><strong>After v1.0 that line changes.</strong> Phases 11–14 take the driver layer past relational: MongoDB and Redis ship from the same core, and the product becomes one client for several <em>kinds</em> of database rather than a Postgres client with a plugin point. The contract work that makes that possible is <code>10-ENGINE-MODEL.md</code>; the engines are <code>11-ENGINE-MONGODB.md</code> and <code>12-ENGINE-REDIS.md</code>; the decision is ADR-034.</p><hr><h2 id="_1-why-build-it" tabindex="-1">1. Why build it <a class="header-anchor" href="#_1-why-build-it" aria-label="Permalink to &quot;1. Why build it&quot;">​</a></h2><p>Existing VS Code DB extensions each fail on at least one axis:</p><table tabindex="0"><thead><tr><th>Gap</th><th>Who has it</th></tr></thead><tbody><tr><td>Drivers installed as separate stale extensions</td><td>SQLTools</td></tr><tr><td>Core features paywalled / closed source</td><td>Database Client (cweijan), DBCode</td></tr><tr><td>Single engine, no growth path</td><td>MS PostgreSQL, MSSQL, MongoDB, Oracle</td></tr><tr><td>Result grid dies past ~50k rows</td><td>almost all</td></tr><tr><td>No <code>NOTICE</code>/<code>RAISE</code> capture, no cursor streaming, numeric precision loss</td><td>almost all</td></tr><tr><td>No prod-safety guardrails</td><td>all</td></tr><tr><td>No EXPLAIN plan visualizer worth using</td><td>all</td></tr></tbody></table><p>Pitta targets: <strong>deep Postgres correctness + a grid that does not fall over + safety on production connections</strong>, all in one open package.</p><h2 id="_2-target-users" tabindex="-1">2. Target users <a class="header-anchor" href="#_2-target-users" aria-label="Permalink to &quot;2. Target users&quot;">​</a></h2><ol><li><strong>App developers</strong> — need to poke at their dev DB without leaving the editor. Care about: fast connect, table browse, edit a row, run a query.</li><li><strong>Data / backend engineers</strong> — care about EXPLAIN, indexes, bloat, long-running sessions, big result sets, exports.</li><li><strong>Teams</strong> — care about shareable connection profiles in the repo with <em>no secrets committed</em>, and prod write-guards.</li></ol><h2 id="_3-two-operating-modes-both-first-class" tabindex="-1">3. Two operating modes (both first-class) <a class="header-anchor" href="#_3-two-operating-modes-both-first-class" aria-label="Permalink to &quot;3. Two operating modes (both first-class)&quot;">​</a></h2><h3 id="ui-mode-—-no-sql-typed" tabindex="-1">UI mode — no SQL typed <a class="header-anchor" href="#ui-mode-—-no-sql-typed" aria-label="Permalink to &quot;UI mode — no SQL typed&quot;">​</a></h3><p>Explorer tree → click object → visual panel.</p><ul><li>Browse servers → databases → schemas → tables/views/functions/types/sequences/extensions.</li><li>Table Data view: paginated/virtualized grid, per-column filter + sort, inline cell edit, insert/delete row, all changes staged then applied as reviewable DML in one transaction.</li><li>Structure view: columns, types, defaults, nullability, PK/FK/unique/check, indexes, triggers, RLS policies, partitions, storage/bloat stats.</li><li>Generated DDL tab for every object.</li><li>ERD canvas per schema.</li></ul><h3 id="query-mode-—-sql-first" tabindex="-1">Query mode — SQL first <a class="header-anchor" href="#query-mode-—-sql-first" aria-label="Permalink to &quot;Query mode — SQL first&quot;">​</a></h3><ul><li><code>.sql</code> files bound to a connection (status bar picker + file-level <code>-- @pitta connection: &lt;name&gt;</code> directive).</li><li>Run statement under cursor / selection / whole file, each into its own result tab.</li><li>Completion, hover, go-to-definition on schema objects; live syntax + semantic diagnostics.</li><li>Query history, saved queries, parameterized snippets.</li><li>SQL notebooks (<code>.psql-nb</code>) mixing markdown + SQL cells + charts.</li><li>EXPLAIN / EXPLAIN ANALYZE tree visualizer.</li></ul><p>Both modes share one connection manager, one metadata cache, one result grid component.</p><h2 id="_4-non-goals-v1" tabindex="-1">4. Non-goals (v1) <a class="header-anchor" href="#_4-non-goals-v1" aria-label="Permalink to &quot;4. Non-goals (v1)&quot;">​</a></h2><ul><li>Not a DBA console: no backup/restore orchestration, no replication management, no server config editing.</li><li>No cross-connection joins, and no cross-<em>engine</em> ones either — that is a query engine, not a client (ADR-048).</li><li>No BI dashboards or scheduled reports.</li><li>No web extension host (<code>vscode.dev</code>) build — native driver dependency. Revisit post-v1.</li><li>No AI/LLM features in v1 core. A separate optional extension may add them later.</li></ul><h2 id="_5-success-criteria-for-v1-0" tabindex="-1">5. Success criteria for v1.0 <a class="header-anchor" href="#_5-success-criteria-for-v1-0" aria-label="Permalink to &quot;5. Success criteria for v1.0&quot;">​</a></h2><ul><li>Connect → browse → run a query in <strong>under 30 s</strong> from a cold install.</li><li><code>SELECT</code> returning <strong>1M rows</strong> streams into the grid without OOM; first page visible in <strong>&lt; 500 ms</strong>.</li><li>Zero secrets ever written to <code>settings.json</code> or any file in the workspace.</li><li>Postgres type fidelity: numeric/decimal never lossy, arrays/json/ranges/enums/composites render correctly, timestamps honor session <code>TimeZone</code>.</li><li>A second driver (SQLite) ships from the same core with <strong>no changes to core packages</strong>.</li></ul><h2 id="_6-success-criteria-for-v1-2-multi-model" tabindex="-1">6. Success criteria for v1.2 (multi-model) <a class="header-anchor" href="#_6-success-criteria-for-v1-2-multi-model" aria-label="Permalink to &quot;6. Success criteria for v1.2 (multi-model)&quot;">​</a></h2><ul><li>A MongoDB collection and a Redis keyspace are browsable, editable, and safe to point at production from the same UI, the same guards, and the same grid.</li><li>Expanding a 1M-key Redis database costs the server nothing measurable — no <code>KEYS</code>, nothing in <code>SLOWLOG</code>.</li><li>A document with fields absent from its neighbours renders those fields as <code>MISSING</code>, not as <code>NULL</code>, and can have a field removed rather than nulled.</li><li>A pasted <code>.mongodb.js</code> snippet cannot execute arbitrary JavaScript in the extension host.</li><li>The MongoDB and Redis PRs add packages and do not edit core — the Phase 11 contract work is what makes that true, and it is done first, in the open.</li></ul>',23)])])}const g=t(r,[["render",s]]);export{p as __pageData,g as default};
